import {primaryDiagram} from './primary-visuals.mjs?v=7.1.0';
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function icon(name,size=22){const paths={times:'m5 5 14 14M19 5 5 19',shirt:'M8 3 3 6l2 5 3-1v10h8V10l3 1 2-5-5-3a4 4 0 0 1-8 0Z',bolt:'m13 2-9 12h7l-1 8 10-12h-7l1-8Z',shop:'M4 8h16l1 13H3L4 8Zm4 0V6a4 4 0 0 1 8 0v2M8 12h0m8 0h0',edit:'m4 16 12-12 4 4L8 20H4v-4Zm10-10 4 4',ball:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20Zm-4 7 4-3 4 3-1.5 5h-5ZM4 6l4 3m8 0 4-3M9.5 14 6 19m8.5-5 3.5 5M12 2v4M2 12l4 1m16-1-4 1',arrow:'M4 12h16m-6-6 6 6-6 6',back:'M20 12H4m6-6-6 6 6 6',check:'m4 12 5 5L20 6',close:'m5 5 14 14M5 19 19 5',play:'m8 4 13 8-13 8Z',pause:'M7 4v16M17 4v16',trophy:'M7 3h10v6a5 5 0 0 1-10 0Zm0 2H3v3a4 4 0 0 0 5 4m9-7h4v3a4 4 0 0 1-5 4m-4 2v6m-5 1h10',chart:'M3 21h19M6 17v-5m6 5V7m6 10V3',grid:'M3 3h7v7H3zm11 0h7v7h-7zM3 14h7v7H3zm11 0h7v7h-7z',home:'m3 10 9-7 9 7v11h-6v-7H9v7H3Z',clock:'M12 7v6l4 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',sound:'M11 4 5 9H2v6h3l6 5Zm4 4a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14',mute:'M11 4 5 9H2v6h3l6 5Zm5 5 6 6m-6 0 6-6',coach:'M12 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M4 21v-2a8 8 0 0 1 16 0v2',settings:'M3 6h18M3 12h18M3 18h18M8 3v6m8 0v6m-6 0v6',help:'M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 4m0 4h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',star:'m12 2 3 6.5 7 1-5 5 1 7-6-3.5L6 21l1-7-5-4.5 7-1Z',plus:'M12 4v16M4 12h16',logout:'M9 4H3v16h6m5-13 5 5-5 5m-7-5h12',shield:'m12 2 9 4v7c0 5-9 9-9 9s-9-4-9-9V6Zm-5 10 4 4 6-7',flame:'M13 2c3 7-2 8 1 11 2-1 3-4 3-4 7 7 3 14-5 14S1 14 7 8c0 5 3 5 3 5-2-6 3-11 3-11',reset:'M3 9a9 9 0 1 1 0 6M3 3v6h6',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',erase:'m9 5-7 7 7 7h12V5Zm4 4 5 6m-5 0 5-6',book:'M12 6c-3-3-7-3-10-1v14c3-2 7-2 10 1m0-14c3-3 7-3 10-1v14c-3-2-7-2-10 1Zm0 0v14',whistle:'M3 15a6 6 0 1 0 6-6H4v6Zm6-6h12v5h-6M17 3v3m4-2-2 3M9 12v3'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.ball}"/></svg>`;}
export function kit(number=9,color='#1647c8',size=110){return `<svg width="${size}" height="${size}" viewBox="0 0 120 120" aria-hidden="true"><path d="m40 13-26 13 12 28 13-6v58h42V48l13 6 12-28-26-13c-6 10-34 10-40 0" fill="${color}"/><path d="m42 13 3 17h30l3-17c-10 7-26 7-36 0" fill="#f8fbf3"/><path d="M52 29h16v77H52" fill="white" opacity=".13"/><path d="m18 35 11 24M102 35 91 59" stroke="#e0fa77" stroke-width="5"/><text x="60" y="79" text-anchor="middle" font-family="Impact,Arial,sans-serif" font-size="36" fill="white">${number}</text><path d="M39 102h42" stroke="black" stroke-opacity=".12" stroke-width="3"/></svg>`;}
export function stadium(){return `<svg viewBox="0 0 570 360" fill="none" aria-hidden="true"><defs><linearGradient id="pitch" x1="400" y1="50" x2="100" y2="350"><stop stop-color="#407c53"/><stop offset="1" stop-color="#1d6843"/></linearGradient><pattern id="net" width="12" height="12" patternUnits="userSpaceOnUse"><path d="M12 0H0v12" stroke="#b1d0b5" stroke-opacity=".6" stroke-width="1"/></pattern></defs><circle cx="420" cy="85" r="150" fill="#295c3b" opacity=".5"/><path d="m88 297 178-200 269 100-177 151Z" fill="#0c352b"/><path d="m74 268 179-199 269 101-178 151Z" fill="url(#pitch)"/><path d="m92 272 178-197m-120 220L328 96m-120 221L386 118m-120 221L444 140" stroke="#8bd162" stroke-opacity=".1" stroke-width="48"/><path d="m94 267 163-182 245 92-163 129Z" stroke="#b0cfb7" stroke-width="2"/><path d="m184 166 249 94" stroke="#b0cfb7" stroke-width="2"/><ellipse cx="310" cy="212" rx="45" ry="25" transform="rotate(-39 310 212)" stroke="#b0cfb7" stroke-width="2"/><path d="m396 127-47 51 84 31 46-43M127 229l46-49 83 31-46 49" stroke="#b0cfb7" stroke-width="2"/><path d="m373 131 1-74 111 35v78Z" fill="url(#net)" stroke="#e7f2d9" stroke-width="4" stroke-linejoin="round"/><path d="m374 57 28-25 111 36-28 24m28-24v77l-28 25" fill="url(#net)" stroke="#e7f2d9" stroke-width="3"/><path d="m374 131 28-23 111 37m-111-37V32" stroke="#a7c4a6" stroke-width="2"/><path d="M135 89V15m0 11-24-1v-15l47 1v16Z" stroke="#6e9184" stroke-width="6"/><path d="M112 17h45" stroke="#e7faad" stroke-width="7"/><path d="M508 198V96m0 13 36 4v-16l-36-4" stroke="#6e9184" stroke-width="5"/><path d="m509 102 34 5" stroke="#e7faad" stroke-width="6"/><path d="M238 243c34-10 72-51 100-68" stroke="#def58d" stroke-width="3" stroke-dasharray="6 7"/><circle cx="237" cy="241" r="24" fill="#e6f0d9"/><path d="m237 228 11 8-4 13h-14l-4-13Z" fill="#153b31"/><path d="m237 217v11m-24 15 13-7m18 13 9 10m-23-10-9 11m27-24 11-4" stroke="#153b31" stroke-width="3"/><ellipse cx="236" cy="270" rx="26" ry="8" fill="#072b22" opacity=".35"/><path d="m164 156-6 35m17-31 5 31" stroke="#d9b28c" stroke-width="7"/><path d="m162 130-9 28 24 5 5-27Z" fill="#c0ed60"/><circle cx="173" cy="122" r="10" fill="#d9b28c"/><path d="m153 139-13 13m42-12 11-6" stroke="#d9b28c" stroke-width="6" stroke-linecap="round"/><path d="m350 245-8 28m19-24 4 27" stroke="#d9b28c" stroke-width="7"/><path d="m349 221-7 28 22 6 7-28Z" fill="#6188ff"/><circle cx="359" cy="213" r="9" fill="#a5704f"/><path d="m345 229-12 9m37-8 12 5" stroke="#a5704f" stroke-width="6" stroke-linecap="round"/><path d="m83 305 5-9 10 4m370-271 3-10 10 4" stroke="#bfe973" stroke-width="3"/><circle cx="205" cy="65" r="4" fill="#bfe973"/><circle cx="536" cy="248" r="3" fill="#bfe973"/></svg>`;}
const svg=(content,w=360,h=210)=>`<svg class="math-visual" viewBox="0 0 ${w} ${h}" role="img" aria-label="Question diagram">${content}</svg>`;
const text=(x,y,s,size=14,attrs='')=>`<text x="${x}" y="${y}" text-anchor="middle" font-size="${size}" font-family="Arial,sans-serif" fill="#183c32" ${attrs}>${esc(s)}</text>`;
export function mathText(value){return esc(value).replace(/(\d+|[?□])\/(\d+|[?□])/g,'<span class="fraction"><span>$1</span><span>$2</span></span>').replace(/\n/g,'<br>');}
export function diagram(v,{angle=30,points=[],bars=[],hour=12,minute=0}={}){
 const primary=primaryDiagram(v,{angle,hour,minute});if(primary!==null)return primary;
 if(!v)return '';
 if(v.type==='fraction')return `<div class="fraction-strip" role="img" aria-label="${v.d} equal parts; count the green parts">${Array.from({length:v.d},(_,i)=>`<i class="${i<v.n?'filled':''}"></i>`).join('')}</div>`;
 if(v.type==='groups')return `<div class="equal-groups">${Array.from({length:v.groups},()=>`<span>${Array.from({length:v.each},()=>'<i></i>').join('')}</span>`).join('')}</div>`;
 if(v.type==='numberline'){const x=35+(v.value-v.lo)/(v.hi-v.lo)*290;return svg(`<path d="M35 110h290" stroke="#667f72" stroke-width="2"/>${Array.from({length:11},(_,i)=>`<path d="M${35+i*29} 104v12" stroke="#667f72"/>`).join('')}${text(35,145,v.lo)}${text(325,145,v.hi)}<circle cx="${x}" cy="92" r="12" fill="#135b41"/>`);}
 if(v.type==='integerline')return svg(`<path d="M25 105h310" stroke="#789084" stroke-width="2"/>${Array.from({length:11},(_,i)=>`<path d="M${25+i*31} 100v10" stroke="#789084"/>${text(25+i*31,132,(i-5)*5,11)}`).join('')}<circle cx="${180+v.value*6.2}" cy="88" r="8" fill="#16664b"/>`,360,160);
 if(v.type==='ruler')return svg(`<rect x="20" y="95" width="320" height="54" rx="6" fill="#fff0bd" stroke="#d7c68e"/>${Array.from({length:61},(_,i)=>`<path d="M${30+i*5} 95v${i%10===0?22:i%5===0?16:9}" stroke="#8a7d55"/>${i%10===0?text(30+i*5,136,i,11):''}`).join('')}<rect x="${30+v.start*5}" y="70" width="${(v.end-v.start)*5}" height="15" rx="3" fill="#4a6ee0"/><path d="M${30+v.start*5} 86v8m${(v.end-v.start)*5} -8v8" stroke="#4a6ee0"/>`,360,175);
 if(v.type==='clock'){let cx=125,cy=111;const hour=(v.h%12+v.m/60)*Math.PI/6-Math.PI/2,min=v.m*Math.PI/30-Math.PI/2;return svg(`<circle cx="${cx}" cy="${cy}" r="91" fill="#fff" stroke="#c8d7cd" stroke-width="4"/>${Array.from({length:60},(_,i)=>{const a=i*Math.PI/30;return `<path d="M${cx+Math.sin(a)*83} ${cy-Math.cos(a)*83} ${cx+Math.sin(a)*(i%5===0?74:80)} ${cy-Math.cos(a)*(i%5===0?74:80)}" stroke="#597063" stroke-width="${i%5===0?2:1}"/>`;}).join('')}${Array.from({length:12},(_,i)=>{const n=i+1,a=n*Math.PI/6;return text(cx+Math.sin(a)*62,cy-Math.cos(a)*62+5,v.roman?['I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII'][i]:n,15);}).join('')}<path d="M${cx} ${cy} ${cx+Math.cos(hour)*43} ${cy+Math.sin(hour)*43}" stroke="#163f32" stroke-width="7" stroke-linecap="round"/><path d="M${cx} ${cy} ${cx+Math.cos(min)*67} ${cy+Math.sin(min)*67}" stroke="#5a7bdf" stroke-width="4" stroke-linecap="round"/><circle cx="${cx}" cy="${cy}" r="6" fill="#163f32"/>`,250,222);}
 if(v.type==='rectangle')return svg(`<rect x="70" y="40" width="220" height="115" rx="1" fill="#edf5e4" stroke="#2e7754" stroke-width="3"/>${text(180,26,`${v.w} ${v.unit}`)}${text(320,105,`${v.h} ${v.unit}`)}${v.missing?text(180,182,'? cm'):''}<path d="M70 142h13v13" fill="none" stroke="#2e7754"/>`);
 if(v.type==='compound')return svg(`<path d="M50 35H${50+240}V${35+(v.h-v.cutH)/v.h*140}H${50+(v.w-v.cutW)/v.w*240}V175H50Z" fill="#edf5e4" stroke="#2e7754" stroke-width="3"/>${text(170,24,`${v.w} cm`)}${text(26,110,`${v.h} cm`)}${text(307,80,`${v.h-v.cutH}`)}${text(235,150,`${v.cutW}`)}${text(115,199,`${v.w-v.cutW}`)}`);
 if(v.type==='solid'){let shape='';if(v.shape==='Sphere')shape='<circle cx="175" cy="105" r="68" fill="#d5e6ff" stroke="#557bc9" stroke-width="3"/><ellipse cx="175" cy="105" rx="68" ry="23" fill="none" stroke="#557bc9" stroke-dasharray="5 4"/>';else if(v.shape==='Cylinder')shape='<path d="M100 60v100a75 24 0 0 0 150 0V60" fill="#d5e6ff" stroke="#557bc9" stroke-width="3"/><ellipse cx="175" cy="60" rx="75" ry="24" fill="#eef4ff" stroke="#557bc9" stroke-width="3"/>';else if(v.shape==='Cone')shape='<path d="m175 25-75 135a75 24 0 0 0 150 0Z" fill="#d5e6ff" stroke="#557bc9" stroke-width="3"/><ellipse cx="175" cy="160" rx="75" ry="24" fill="#b9d1f8" stroke="#557bc9" stroke-width="3"/>';else if(v.shape==='Square pyramid')shape='<path d="m175 25-85 130 90 35 80-55Z" fill="#d5e6ff" stroke="#557bc9" stroke-width="3"/><path d="m175 25 5 165m-90-35 80-30 90 10" fill="none" stroke="#557bc9" stroke-dasharray="5 4"/>';else{const x=v.shape==='Cube'?100:70,w=v.shape==='Cube'?110:160;shape=`<path d="m${x} 70 45-35h${w}v110l-45 35H${x}Z" fill="#bdd4f6" stroke="#557bc9" stroke-width="3"/><path d="M${x} 70h${w}v110m0-110 45-35" fill="none" stroke="#557bc9" stroke-width="3"/><path d="M${x} 70v110h${w}" fill="#dceaff" stroke="#557bc9" stroke-width="3"/>`;}return svg(shape);}
 if(v.type==='lines')return svg(v.kind==='Parallel'?'<path d="m75 70 200-35M75 150l200-35" stroke="#446ac7" stroke-width="5"/>':v.kind==='Perpendicular'?'<path d="M70 110h220M175 30v150" stroke="#446ac7" stroke-width="5"/><path d="M175 110h18V92h-18" fill="none" stroke="#446ac7" stroke-width="2"/>':'<path d="m80 40 180 130M80 150l180-90" stroke="#446ac7" stroke-width="5"/>');
 if(v.type==='angle'||v.type==='drawAngle'){const deg=v.type==='drawAngle'?angle:v.degrees,rad=-deg*Math.PI/180,cx=160,cy=150,r=105,ex=cx+Math.cos(rad)*r,ey=cy+Math.sin(rad)*r;let protractor='';if(v.protractor||v.type==='drawAngle'){const limit=deg>180?360:180;protractor=`<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="#d7e0d5"/>`+Array.from({length:limit/10+1},(_,i)=>{const a=-i*10*Math.PI/180;return `<path d="M${cx+Math.cos(a)*(r-5)} ${cy+Math.sin(a)*(r-5)} ${cx+Math.cos(a)*(r+3)} ${cy+Math.sin(a)*(r+3)}" stroke="#b0beb3"/>${i%3===0?text(cx+Math.cos(a)*(r+18),cy+Math.sin(a)*(r+18)+3,i*10,9):''}`;}).join('');}return svg(`${protractor}<path d="M${cx+r} ${cy}H${cx}L${ex} ${ey}" fill="none" stroke="#2b6750" stroke-width="4" stroke-linecap="round"/><path d="M${cx+32} ${cy}A32 32 0 ${deg>180?1:0} 0 ${cx+Math.cos(rad)*32} ${cy+Math.sin(rad)*32}" fill="none" stroke="#6891df" stroke-width="2"/><circle cx="${cx}" cy="${cy}" r="4" fill="#2b6750"/>`,350,deg>180?290:210);}
 if(v.type==='polygon'){const p=Array.from({length:v.sides},(_,i)=>{const a=-Math.PI/2+i*2*Math.PI/v.sides,r=!v.regular&&i===0?45:80;return `${180+Math.cos(a)*r},${110+Math.sin(a)*r}`;}).join(' ');return svg(`<polygon points="${p}" fill="#e2edff" stroke="#5276c8" stroke-width="3"/>`);}
 if(v.type==='areaGrid')return `<div class="area-grid" role="img" aria-label="Each small square is one square centimetre">${Array.from({length:30},(_,i)=>`<i class="${i<v.full?'full':i<v.full+v.half?'half':''}"></i>`).join('')}</div>`;
 if(v.type==='cubeStack'){const cells=[];for(let z=0;z<v.depth;z++)for(let y=0;y<v.h;y++)for(let x=0;x<v.w;x++){const px=65+x*27+z*14,py=165-y*27-z*10;cells.push(`<path d="m${px} ${py} 14-10 27 0v27l-14 10h-27Z" fill="#b9d3ef" stroke="#5b85bb"/><path d="M${px} ${py}h27v27m0-27 14-10" fill="#dce9ff" stroke="#5b85bb"/>`);}return svg(cells.join(''));}
 if(v.type==='coordinate'){const g=Array.from({length:9},(_,i)=>`<path d="M${40+i*30} 15v240M40 ${255-i*30}h240" stroke="#dfe7de"/>${text(40+i*30,275,i,10)}${text(22,259-i*30,i,10)}`).join('');const x=40+v.x*30,y=255-v.y*30;return svg(`${g}<path d="M40 15v240h240" fill="none" stroke="#718579" stroke-width="2"/>${v.mirror?`<path d="M${40+v.mirror*30} 15v240" stroke="#d69e42" stroke-width="2" stroke-dasharray="5 4"/>`:''}<path d="m${x} ${y} 30 0 0-30Z" fill="#dce8ff" stroke="#6489d0" stroke-width="2"/><circle cx="${x}" cy="${y}" r="5" fill="#315fb5"/>${text(x-12,y-10,'A',13)}`,330,290);}
 if(['barChart','lineGraph','pictogram','dataTable','barBuild'].includes(v.type)){
  if(v.type==='dataTable'||v.type==='barBuild')return `<table class="question-table"><thead><tr>${v.labels.map(l=>`<th>${esc(l)}</th>`).join('')}</tr></thead><tbody><tr>${v.values.map(n=>`<td>${n}</td>`).join('')}</tr></tbody></table>`;
  if(v.type==='pictogram')return `<div class="pictogram">${v.labels.map((l,i)=>`<div><b>${esc(l)}</b><span>${Array.from({length:v.values[i]/v.scale},()=>icon('ball',15)).join('')}</span></div>`).join('')}<small>1 ${icon('ball',12)} = ${v.scale} goals</small></div>`;
  const max=20,base=170,xx=i=>65+i*70,yy=value=>base-value*7;let c=Array.from({length:11},(_,i)=>`<path d="M40 ${yy(i*2)}h285" stroke="#e1e8dd"/>${text(22,yy(i*2)+4,i*2,10)}`).join('');c+='<path d="M40 25v145h285" stroke="#78907d" fill="none"/>';
  c+=v.labels.map((l,i)=>`${v.type==='barChart'?`<rect x="${xx(i)-17}" y="${yy(v.values[i])}" width="34" height="${v.values[i]*7}" rx="3" fill="${['#2c7c57','#618ce6','#dfbe58','#75a391'][i]}"/>`:`<circle cx="${xx(i)}" cy="${yy(v.values[i])}" r="5" fill="#3d6ac8"/>`}${text(xx(i),195,l,11)}`).join('');if(v.type==='lineGraph')c+=`<polyline points="${v.values.map((n,i)=>`${xx(i)},${yy(n)}`).join(' ')}" fill="none" stroke="#3d6ac8" stroke-width="3"/>`;return svg(c);
 }
 if(v.type==='timetable')return `<table class="question-table timetable"><thead><tr><th>Stop</th><th>Arrive</th></tr></thead><tbody>${v.labels.map((l,i)=>`<tr><th>${esc(l)}</th><td>${Math.floor(v.times[i]/60)}:${String(v.times[i]%60).padStart(2,'0')}</td></tr>`).join('')}</tbody></table>`;
 return '';
}
